args.query:
\dt api.*
\dv api.*
\d api.application
\d api.company
\d api.app_user
select grantee, table_name, privilege_type from information_schema.table_privileges where table_schema='api' order by 2,1,3;
select tablename, policyname, roles, cmd, qual, with_check from pg_policies;
select relname, relrowsecurity, relforcerowsecurity, reloptions from pg_class where relnamespace='api'::regnamespace and relkind in ('r','v');
select * from api.app_user;
select tgname, tgrelid::regclass from pg_trigger where not tgisinternal;

select * from api.status;
\df+ priv.*
select rolname from pg_roles where rolname in ('lawyer','anon','authenticator');
select grantee,privilege_type from information_schema.table_privileges where table_name='application' and grantee='applicant';
select pg_get_functiondef('priv.my_company'::regproc);

begin;
create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create function priv.check_contract() returns trigger language plpgsql security definer set search_path=api as $$
begin
 if not exists (select 1 from api.application where id=new.application_id and status_id=priv.status_id('Одобрена')) then
  raise exception 'Договор можно заключить только по одобренной заявке';
 end if;
 return new;
end$$;
create trigger contract_check before insert or update of application_id on api.contract for each row execute function priv.check_contract();
alter table api.contract enable row level security;
create policy contract_admin on api.contract for all to fund_admin using (true) with check (true);
create policy contract_lawyer on api.contract for all to lawyer using (true) with check (true);
create policy contract_applicant on api.contract for select to applicant using (exists (select 1 from api.application a where a.id=application_id and a.company_id=priv.my_company()));
grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
grant usage on sequence api.contract_id_seq to fund_admin, lawyer;
grant usage on schema api to lawyer;
grant select on api.application, api.company, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using (true);
update api.app_user set role='lawyer' where login='lawyer1';
create view api.limit_balance with (security_invoker=true) as
select c.name as company, c.funding_limit,
 coalesce(ap.s,0) as approved,
 coalesce(ct.s,0) as contracted,
 c.funding_limit - coalesce(ct.s,0) as remaining
from api.company c
join (select company_id, sum(amount) s from api.application where status_id=priv.status_id('Одобрена') group by 1) ap on ap.company_id=c.id
left join (select a.company_id, sum(k.amount) s from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_id=c.id;
grant select on api.limit_balance to fund_admin, lawyer;
commit;
